package com.github.nyabanban.fuji.emulator.components.flashimage

import com.github.nyabanban.fuji.emulator.api.*
import org.junit.jupiter.api.Test
import org.junit.jupiter.api.io.TempDir
import java.nio.ByteBuffer
import java.nio.ByteOrder
import java.nio.file.Files
import java.nio.file.Path
import java.security.MessageDigest
import kotlin.test.*

class ProgrammableRegionTest {
 @TempDir lateinit var home:Path
 private val offset=0x3dc0000L
 private fun hash(b:ByteArray)=java.util.HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b))
 private class Context(override val directory:Path,val data:Map<String,Map<String,Any?>> = emptyMap()):ComponentContext {
  val claims=linkedMapOf<String,Any>()
  override fun readData(relative:String)=data.getValue(relative)
  override val clock=EmulationClock{0}
  override val ports=object:Ports{override fun <T:Any> register(owner:String,name:String,type:Class<T>,port:T){check(claims.putIfAbsent(name,port)==null)};override fun <T:Any> find(name:String,type:Class<T>):T?=claims[name]?.let{type.cast(it)};override fun removeOwner(owner:String){} }
  override val events=object:EventChannel{override fun publish(event:ComponentEvent){};override fun subscribe(listener:(ComponentEvent)->Unit)=AutoCloseable{}}
  override fun dataPath(relative:String)=directory.resolve(relative).normalize().also{require(it.startsWith(directory))}
 }
 private fun seed(fill:Int=255)=ByteArray(131072){fill.toByte()}.also{Files.write(home.resolve("seed.img"),it)}
 private fun identity(b:ByteArray)=ImageRegionIdentity("seed",offset,b.size.toLong(),hash(b),"seed.img")
 private fun spec(b:ByteArray)=mapOf<String,Any?>("schema" to 1,"profile" to WritableRegion.PROGRAM_PROFILE,"regionId" to "seed","file" to "copy.img","mode" to "create","sha256" to hash(b),"writableOffset" to(offset+4096),"writableLength" to 65536L,"programPageBytes" to 256,"programLaw" to WritableRegion.PROGRAM_LAW)
 private fun open(b:ByteArray,s:Map<String,Any?> = spec(b))=WritableRegion(Context(home),s,listOf(identity(b))){at,dst->require(at>=offset&&dst.remaining()<=b.size-(at-offset));dst.put(b,(at-offset).toInt(),dst.remaining())}
 @Test fun commitPersistsExact256FrozenBytesAndPreservesEveryOtherByteAndSeed(){
  val b=seed();val payload=ByteBuffer.allocateDirect(264);repeat(264){payload.put(it,(it xor 0x5a).toByte())};payload.position(4);payload.limit(260);val frozen=ByteArray(256){payload.get(4+it)};val expected=b.clone().also{frozen.copyInto(it,4096)}
  open(b).use{image->val tx=image.prepareProgram(offset+4096,payload.asReadOnlyBuffer());assertEquals(4,payload.position());assertEquals(260,payload.limit());assertContentEquals(b,Files.readAllBytes(home.resolve("copy.img")));val before=ByteBuffer.allocate(256);image.overlay(offset+4096,before,0,256);assertContentEquals(ByteArray(256){-1},before.array());repeat(256){payload.put(4+it,0)}
   val receipt=tx.commit();assertEquals(256,receipt.size);assertEquals(offset+4096,receipt.offset);assertEquals(frozen.count{it!=(-1).toByte()}.toLong(),receipt.changedBytes);assertEquals(hash(frozen),receipt.payloadSha256);assertEquals(hash(b),receipt.beforeSha256);assertEquals(hash(expected),receipt.afterSha256);assertEquals(1L,receipt.generation);assertFalse(image.snapshot().pending);assertFails{tx.commit()};tx.close();assertContentEquals(expected,Files.readAllBytes(home.resolve("copy.img")));assertContentEquals(b,Files.readAllBytes(home.resolve("seed.img")))}
 }
 @Test fun boundsLengthPageCrossingAndPermissionsRefuseWithoutLeaseOrPayloadMovement(){val b=seed();open(b).use{image->for((at,n)in listOf(offset to 1,offset+4095 to 1,offset+4096 to 0,offset+4096 to 257,offset+4096+255 to 2,offset+69632 to 1,-1L to 1,Long.MAX_VALUE to 1)){val p=ByteBuffer.wrap(ByteArray(n));val before=image.snapshot();assertFails{image.prepareProgram(at,p)};assertEquals(0,p.position());assertEquals(before,image.snapshot())};assertContentEquals(b,Files.readAllBytes(home.resolve("copy.img")))}}
 @Test fun oneToZeroStrictLawRefusesZeroToOneBeforeOwnershipAndAllowsFurtherClears(){val b=seed(0xa5);open(b).use{image->for(v in listOf(0xff,0xa7,0x40)){val before=image.snapshot();assertFails{image.prepareProgram(offset+4096,ByteBuffer.wrap(byteArrayOf(v.toByte())))};assertEquals(before,image.snapshot())};val r=image.prepareProgram(offset+4096,ByteBuffer.wrap(byteArrayOf(0xa0.toByte()))).commit();assertEquals(1L,r.changedBytes);assertFails{image.prepareProgram(offset+4096,ByteBuffer.wrap(byteArrayOf(0xa5.toByte())))};assertEquals(0xa0.toByte(),Files.readAllBytes(home.resolve("copy.img"))[4096])}}
 @Test fun cancellationAndCloseReleaseSharedEraseOwnershipWithoutCommit(){val b=seed();val image=open(b);val p=image.prepareProgram(offset+4096,ByteBuffer.wrap(byteArrayOf(0)));assertFails{image.prepareErase(offset+4096,4096)};assertFails{image.prepareProgram(offset+4096,ByteBuffer.wrap(byteArrayOf(0)))};p.close();assertFails{p.commit()};val e=image.prepareErase(offset+4096,4096);assertFails{image.prepareProgram(offset+4096,ByteBuffer.wrap(byteArrayOf(0)))};e.close();val pending=image.prepareProgram(offset+4096,ByteBuffer.wrap(byteArrayOf(0)));image.close();assertFails{pending.commit()};assertTrue(image.snapshot().closed);assertFalse(image.snapshot().pending);assertContentEquals(b,Files.readAllBytes(home.resolve("copy.img")));open(b,spec(b)+mapOf("mode" to "resume")).close()}
 @Test fun programAndEraseShareMonotonicGenerationAndReadback(){val b=seed();open(b).use{image->val p=image.prepareProgram(offset+4096,ByteBuffer.wrap(ByteArray(256))).commit();val expected=b.clone().also{it.fill(0,4096,4352)};assertEquals(hash(expected),p.afterSha256);val e=image.prepareErase(offset+4096,4096).commit();assertEquals(2L,e.generation);assertEquals(hash(b),e.afterSha256);assertEquals(256L,e.changedBytes);assertEquals(1,image.programHistory().size);assertEquals(1,image.history().size);assertEquals(1L,image.prepareProgram(offset+4096+255,ByteBuffer.wrap(byteArrayOf(0))).commit().changedBytes)}}
 @Test fun externalDiskEditRefusesPrepareAndCommitWithoutOverwritingIt(){val b=seed();open(b).use{image->val tx=image.prepareProgram(offset+4096,ByteBuffer.wrap(byteArrayOf(0)));val external=b.clone().also{it[100000]=3};Files.write(home.resolve("copy.img"),external);assertFails{tx.commit()};assertNotNull(image.snapshot().failure);assertTrue(image.snapshot().pending);assertEquals(0L,image.snapshot().generation);assertContentEquals(external,Files.readAllBytes(home.resolve("copy.img")));assertFails{image.prepareProgram(offset+4096,ByteBuffer.wrap(byteArrayOf(0)))}}}
 @Test fun collidingTemporaryFileLeavesFailedPendingAndOriginalBytes(){val b=seed();open(b).use{image->val tx=image.prepareProgram(offset+4096,ByteBuffer.wrap(byteArrayOf(0)));val canary=byteArrayOf(7,8);Files.write(home.resolve("copy.img.txn-1.tmp"),canary);assertFails{tx.commit()};assertEquals(0L,image.snapshot().generation);assertNotNull(image.snapshot().failure);assertTrue(image.snapshot().pending);assertContentEquals(b,Files.readAllBytes(home.resolve("copy.img")));assertContentEquals(canary,Files.readAllBytes(home.resolve("copy.img.txn-1.tmp")))}}
 @Test fun resumeUsesExplicitCurrentHashAndRetainsReadonlyCanaries(){val b=seed();open(b).use{it.prepareProgram(offset+4096,ByteBuffer.wrap(byteArrayOf(0x55))).commit()};val current=Files.readAllBytes(home.resolve("copy.img"));assertFails{open(b,spec(b)+mapOf("mode" to "resume"))};open(b,spec(b)+mapOf("mode" to "resume","sha256" to hash(current))).use{image->assertEquals(hash(current),image.snapshot().currentSha256);assertFails{image.prepareProgram(offset,ByteBuffer.wrap(byteArrayOf(0)))}};assertContentEquals(b,Files.readAllBytes(home.resolve("seed.img")))}
 @Test fun unchangedProgramsStillCommitAndHistoryIsBounded(){val b=seed();open(b).use{image->repeat(65){val r=image.prepareProgram(offset+4096,ByteBuffer.wrap(byteArrayOf(-1))).commit();assertEquals(0L,r.changedBytes);assertEquals((it+1).toLong(),r.generation)};assertEquals(64,image.programHistory().size);assertEquals(2L,image.programHistory().first().generation);assertEquals(65L,image.snapshot().generation);assertContentEquals(b,Files.readAllBytes(home.resolve("copy.img")))}}
 @Test fun newProfileRequiresExactExplicitLawPageAndSchemaAndOldProfileRefusesProgram(){val b=seed();for(s in listOf(spec(b)-"programLaw",spec(b)-"programPageBytes",spec(b)+mapOf("programLaw" to "unknown"),spec(b)+mapOf("programPageBytes" to 512),spec(b)+mapOf("programPageBytes" to 256.0),spec(b)+mapOf("unknown" to 1))){assertFails{open(b,s)};assertFalse(Files.exists(home.resolve("copy.img")));assertFalse(Files.exists(home.resolve("copy.img.lock")))};open(b,spec(b).filterKeys{it!="programLaw"&&it!="programPageBytes"}+mapOf("profile" to WritableRegion.PROFILE)).use{assertFalse(it.programEnabled);assertFails{it.prepareProgram(offset+4096,ByteBuffer.wrap(byteArrayOf(0)))};assertFalse(it.snapshot().pending)}}
 @Test fun capturedNaturalPayloadProgramsExactlyOneSelectedPageAfterErase(){
  val ff=checkNotNull(javaClass.getResourceAsStream("/gfx100s-213/attempted-program-page.bin")).use{it.readAllBytes()};assertEquals(256,ff.size);assertEquals("f2606be16ea79dadf91f36b6e8abf15521502c147a9d3925e556165aca6c4004",hash(ff))
  val b=seed(0);open(b).use{image->image.prepareErase(offset+4096,4096).commit();val expected=b.clone().also{it.fill(-1,4096,8192);ff.copyInto(it,4096)};val result=image.prepareProgram(offset+4096,ByteBuffer.wrap(ff)).commit();assertEquals(254L,result.changedBytes);assertEquals(2L,result.generation);assertEquals(hash(expected),result.afterSha256);assertContentEquals(expected,Files.readAllBytes(home.resolve("copy.img")));assertContentEquals(b,Files.readAllBytes(home.resolve("seed.img")))}
 }
 @Test fun actualFactoryPublishesProgramCapabilityOnlyForMatchingExplicitV2(){
  val b=seed();val s=spec(b);val row=mapOf("id" to "seed","offset" to offset,"length" to b.size.toLong(),"file" to "seed.img","sha256" to hash(b));val context=Context(home,mapOf("regions.json" to mapOf("schema" to 1,"profile" to SupplementalRegions.PROFILE,"regions" to listOf(row)),"mutable.json" to s));val raw=ByteArray(0x274+4096){0xdd.toByte()};ByteBuffer.wrap(raw).order(ByteOrder.LITTLE_ENDIAN).putInt(0,6).putInt(0x24c,4096);context.claims["test.update"]=object:UpdateDataPort{override val size=raw.size.toLong();override val sha256=hash(raw);override fun read(offset:Long,destination:ByteBuffer){destination.put(raw,offset.toInt(),destination.remaining())}}
  val defaults=FlashImageFactory().descriptor.settings.associate{it.key to it.default};val settings=defaults+mapOf("sourcePort" to "test.update","regionsProfile" to SupplementalRegions.PROFILE,"regionsFile" to "regions.json","mutationProfile" to WritableRegion.PROFILE,"mutationFile" to "mutable.json");assertFails{FlashImageFactory().create(context,settings)};assertFalse(Files.exists(home.resolve("copy.img")))
  FlashImageFactory().create(context,settings+mapOf("mutationProfile" to WritableRegion.PROGRAM_PROFILE)).use{component->val port=checkNotNull(context.ports.find("flash.image.program",ProgrammableImagePort::class.java));val ro=checkNotNull(context.ports.find("flash.image",ReadOnlyImagePort::class.java));assertEquals(WritableRegion.PROGRAM_LAW,component.state()["programLaw"]);port.prepareProgram(offset+4096,ByteBuffer.wrap(byteArrayOf(0x5a))).commit();val dst=ByteBuffer.allocate(1);ro.read(offset+4096,dst);assertEquals(0x5a.toByte(),dst.array()[0]);assertEquals(1,(component.state()["programHistory"] as List<*>).size)}
 }
}
